SELECT EXISTS(
    SELECT 1 FROM users
    WHERE username = #{username}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM users
    WHERE email = #{email}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM users
    WHERE username = #{username}
      AND id <> #{id}
      AND deleted_at IS NULL
)

SELECT EXISTS(
    SELECT 1 FROM users
    WHERE email = #{email}
      AND id <> #{id}
      AND deleted_at IS NULL
)
